mapper.select:
SELECT s.camunda_task_id AS camundaTaskId, s.id AS stepId, p.id AS processId, p.entity_type AS entityType, p.entity_id AS entityId, p.entity_number AS entityNumber, p.entity_title AS entityTitle, p.requester_id AS requesterId, p.requester_department_id AS requesterDepartmentId, p.total_amount AS totalAmount, p.currency AS currency, p.priority AS priority, s.step_index AS stepIndex, s.step_type AS stepType, s.sla_deadline AS slaDeadline, s.approver_id AS approverId, s.delegate_id AS delegateId, s.assigned_at AS assignedAt FROM approval.approval_processes p JOIN approval.approval_steps s ON s.process_id = p.id WHERE p.status = 'RUNNING' AND p.is_deleted = FALSE AND s.status = 'PENDING' AND s.is_deleted = FALSE AND (s.approver_id = #{userId} OR s.delegate_id = #{userId})
AND p.priority = #{priority}
AND p.entity_type = #{entityType}
AND p.total_amount >= #{minAmount}
AND NOW() > s.sla_deadline
AND s.sla_deadline >= NOW()
ORDER BY
s.sla_deadline s.assigned_at p.total_amount s.sla_deadline
DESC ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM approval.approval_processes p JOIN approval.approval_steps s ON s.process_id = p.id WHERE p.status = 'RUNNING' AND p.is_deleted = FALSE AND s.status = 'PENDING' AND s.is_deleted = FALSE AND (s.approver_id = #{userId} OR s.delegate_id = #{userId})
AND p.priority = #{priority}
AND p.entity_type = #{entityType}
AND p.total_amount >= #{minAmount}
AND NOW() > s.sla_deadline
AND s.sla_deadline >= NOW()
